import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Day08 · General execution kernel and native 30-case evaluation","description":"","frontmatter":{"title":"Day08 · General execution kernel and native 30-case evaluation","outline":false},"headers":[],"relativePath":"en/log/day-08.md","filePath":"en/log/day-08.md","lastUpdated":1794450976000}'),s={name:"en/log/day-08.md"};function n(r,e,i,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[d(`<p>From 2026-11-11 to 11-12, Hearth upgraded <code>native</code> from a compact coding loop to a general execution kernel and measured 30 offline cases through the standalone evaluation repository. The 16 plan items on 11-11 touched 81 files (+7,156/−850); after baseline <code>4617419</code>, another 91 commits on 11-12 (19 files, +2,358/−17) focused on evaluation-result normalization and final fixes. The final fix commit is <code>eb32ad5</code>, followed by documentation.</p><h2 id="general-execution-kernel" tabindex="-1">General execution kernel <a class="header-anchor" href="#general-execution-kernel" aria-label="Permalink to &quot;General execution kernel&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Files and commands</td><td>Added glob/grep, document reads, and XLSX/CSV/DOCX generation; <code>edit_file</code> previews diffs, patches validate every target before atomic writes, and move and real delete are supported; full shell output goes to the task-local <code>.hearth/shell</code> log with only the tail returned, and a timeout kills the whole process tree</td></tr><tr><td>Context and stability</td><td>The model window defaults to 128K and max output to 8K; the runtime reserves <code>max(16K, 15%)</code> and keeps about 20K recent tokens, compacts only at complete turn boundaries, never splits a tool call from its result, and writes a checkpoint after compaction; plain text no longer counts as completion, and repeated turns without <code>finish_task</code> fail; 429/5xx/network errors retry at most twice, and a repeated tool call with identical arguments is flagged and not executed again</td></tr><tr><td>Skills and delegation</td><td>The prompt injects only a skill index; <code>load_skill</code> verifies the content hash, task permission, and audit before returning the body, and <code>read_skill_resource</code> stays inside the package; <code>delegate_task</code> uses a fresh context, allows only read-only or isolated writes, is single-layer and serial with at most two children per parent, forbids MCP and automatic merging, and charges child usage to the parent</td></tr><tr><td>Projects and worktrees</td><td>Added a local Git project registry with path and Git-root validation, branch validation, and a settings list; project tasks use an isolated <code>hearth/&lt;task-id&gt;</code> worktree, reuse it on resume, keep it on success or failure, and delete it only on explicit user cleanup when the worktree is clean; GitHub tasks continue through Codex</td></tr><tr><td>Local MCP</td><td>stdio only; server command, arguments, and encrypted environment values are managed in settings; startup probing, tool discovery, timeouts, and crash isolation form a loop; tools are named <code>mcp__&lt;serverId&gt;__&lt;toolName&gt;</code>, arguments are validated against JSON Schema with <code>ajv</code>, results are bounded, output/errors/stderr are redacted, and cross-server or built-in name conflicts are detected</td></tr><tr><td>Search and approval</td><td>Search is off by default and supports only Tavily and SearXNG; public network access still blocks DNS, redirect, and private-address escapes, and every fetch still requires approval; every MCP call enters the existing per-call approval with server, tool, and argument digest binding, and only full-permission mode auto-approves with an audit event</td></tr></tbody></table><p>The boundaries are explicit: no remote MCP, OAuth, browser-automation search, image/scanned-document understanding, PPTX, LSP, formatters, background shell sessions, or automatic cherry-pick. More tools do not prove that execution quality has passed real-user acceptance.</p><h2 id="native-30-case-evaluation" tabindex="-1">Native 30-case evaluation <a class="header-anchor" href="#native-30-case-evaluation" aria-label="Permalink to &quot;Native 30-case evaluation&quot;">​</a></h2><p>The evaluation used 30 offline cases from <code>hearthproject/hearth-eval</code> (evenly sampled from eight task families), the <code>native</code> executor only, one repetition, auto-scoring and auto-retry enabled, and concurrency 4.</p><table tabindex="0"><thead><tr><th>Stage</th><th style="text-align:right;">Result</th></tr></thead><tbody><tr><td>Initial baseline <code>EXP-20261111051349-b71b80</code></td><td style="text-align:right;">0/30 passed; evaluation-bridge tasks carried an empty <code>permissions.tools</code>, so every tool was filtered out</td></tr><tr><td>First complete 30-case run <code>EXP-20261111141538-011506</code></td><td style="text-align:right;">15/30 passed (50%), average 81.33</td></tr><tr><td>Best complete 30-case run <code>EXP-20261111145332-7a95ea</code></td><td style="text-align:right;"><strong>18/30 passed (60%)</strong>, average 88.89</td></tr><tr><td>Most recent complete 30-case run <code>EXP-20261112003215-b1172b</code></td><td style="text-align:right;">12/30 passed (40%), average 73.33</td></tr><tr><td>Cumulative targeted confirmation</td><td style="text-align:right;"><strong>19/30</strong> cases reached 100 at least once</td></tr></tbody></table><p>The most recent complete run was affected by slow provider responses, truncated scoring JSON, and task timeouts, and it predates the final four normalization fixes, so it cannot be treated as the final code capability. The cumulative 19/30 comes from different runs and targeted retries, not one continuous experiment. Final commit <code>eb32ad5</code> has not been retested in one uninterrupted 30-case run; this validation boundary must stay visible.</p><p>Fixes concentrated in three groups: evaluation bridge and runtime (restore the default tool allowlist, task-scoped approval mode, forbid evaluation-task handoff, shell access for code tasks, transient retries, machine-readable facts gate); result contracts and normalization (blocking counts, conflict flags, alternate slots, next queries, flat metadata, required fields, desktop move/delete counts); prompt contracts (contract tests, direct delivery, recovery final state, rollback section, regression checks).</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>On 2026-11-12 on the current branch:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 100 test files, 725 tests passed</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # TypeScript type check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Web control surface</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # VitePress documentation site</span></span></code></pre></div><p><code>vitest.config.ts</code> raises the per-test timeout to 20 seconds so Git, worktree, and MCP-probe tests on Windows are not failed by the default 5-second timeout. The standalone evaluation repository has 11 test files and 42 tests; <code>npm run typecheck:scenarios</code> now passes with a module declaration for <code>turndown-plugin-gfm</code>.</p><h2 id="selected-commits" tabindex="-1">Selected commits <a class="header-anchor" href="#selected-commits" aria-label="Permalink to &quot;Selected commits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Commit</th><th>Change</th></tr></thead><tbody><tr><td><code>0a26af5</code></td><td>Added glob and safe grep</td></tr><tr><td><code>49d883d</code></td><td>Made file edits atomic with diff preview</td></tr><tr><td><code>cc83883</code></td><td>Hardened shell execution and process-tree timeout</td></tr><tr><td><code>c7cd318</code></td><td>Added office artifact tools</td></tr><tr><td><code>bfc7478</code></td><td>Added web research tools</td></tr><tr><td><code>babb0c2</code></td><td>Added token-aware context compaction</td></tr><tr><td><code>58d0ccf</code></td><td>Loaded skills on demand</td></tr><tr><td><code>96559e9</code> / <code>c659692</code></td><td>Added local Git project registry and isolated worktrees</td></tr><tr><td><code>909431e</code></td><td>Added bounded subagents</td></tr><tr><td><code>09741da</code> / <code>276a91f</code></td><td>Added local MCP management and approval-bound tool calls</td></tr><tr><td><code>0df47a3</code> / <code>238b14b</code> / <code>cee1e02</code></td><td>Restored evaluation task tools, task-scoped approval, and no handoff</td></tr><tr><td><code>05bb8de</code> / <code>4f992c4</code> / <code>6bb4479</code> / <code>eb32ad5</code></td><td>Final four result-normalization fixes</td></tr></tbody></table><p>See <a href="/hearth-os/en/evaluation/">Evaluation and Results</a> for the reports and reproduction steps, and <a href="/hearth-os/en/delivery/status.html">Delivery Status</a> for the Phase 2–6 capability matrix.</p>`,16)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
